from taf.gnb.oam.coam.cu.interfaces.cuoam23r3 import CUOAM23R3
from taf.gnb.oam.coam.cu.schemas.licensed.fm.active_alarms_v2 import (
    ActiveAlarmsLicensedV2,
)
from taf.gnb.oam.coam.cu.schemas.licensed.fm.historical_alarms_v2 import (
    HistoricalAlarmsLicensedV2,
)
from taf.gnb.oam.coam.cu.services.internal.fm.fm_v2 import FMv2
from taf.gnb.oam.coam.cu.services.licensed.fm.fm_licensed_v2 import FMLICENSEDv2
from taf.gnb.oam.coam.cu.utilities.use_m2m_parser import enforce_use_m2m_type


class CUOAM24R1(CUOAM23R3):
    def __init__(self, con_details):
        super(CUOAM24R1, self).__init__(con_details)
        self.fm_v2 = FMv2(con_details=self.con_details)
        self.fm_licensed_v2 = FMLICENSEDv2(con_details=self.con_details)

    @enforce_use_m2m_type
    def get_active_alarms(self, timeout=30, use_m2m=True, raw=False, **kwargs):
        if use_m2m:
            active_alarms = self.fm_licensed_v2.get_active_alarms(timeout=timeout, **kwargs)
        else:
            active_alarms = self.fm_v2.get_active_alarms(timeout=timeout, **kwargs)

        return active_alarms if raw else ActiveAlarmsLicensedV2.from_object_dict(active_alarms)

    @enforce_use_m2m_type
    def get_historical_alarms(self, timeout=30, use_m2m=True, raw=False, **kwargs):
        if use_m2m:
            history = self.fm_licensed_v2.get_historical_alarms(timeout=timeout, **kwargs)
        else:
            history = self.fm_v2.get_historical_alarms(timeout=timeout, **kwargs)

        return history if raw else HistoricalAlarmsLicensedV2.from_object_dict(history)
